const e=[{id:"location",title:"독도는 어디에 있고 어떤 모습인가요?",summary:"울릉도에서 남동쪽으로 87.4km, 동도·서도와 89개 바위섬으로 이루어진 화산섬",content:"독도는 우리나라 동해의 동쪽 끝에 있으며, 독도에 가려면 먼저 울릉도를 거쳐야 합니다. 독도는 동도와 서도라는 두 큰 섬, 그리고 89개의 작은 바위섬으로 이루어져 있습니다. 오래전 화산 활동으로 만들어진 섬이 오랜 시간 파도와 바람을 맞으며 지금의 모습을 갖추었습니다.",points:["울릉도에서 독도까지의 거리는 약 87.4km입니다.","동도와 서도는 서로 다른 높이와 모양을 가진 큰 섬입니다.","독도의 바위 이름은 한반도바위, 코끼리바위처럼 모양을 관찰해 붙은 경우가 많습니다."],sourceLabel:"초등 3~4학년 위치·여행 단원, 중등 위치 단원, 고등 위치와 영역 단원"},{id:"records",title:"독도라는 이름은 어떻게 기록되었나요?",summary:"우산도·석도·독도와 여러 지도 이름을 기록의 맥락 속에서 비교하기",content:"독도를 이해하려면 이름이 바뀌어 온 과정과 기록이 만들어진 맥락을 함께 살펴봐야 합니다. 세종실록지리지에는 우산도와 무릉도가 함께 기록되어 있고, 대한제국 칙령 제41호에는 석도라는 이름이 나타납니다. 학습 자료는 독도라는 이름의 뜻, 우리 기록 속 이름, 다른 나라 지도에서 사용한 이름을 비교하며 자료를 읽도록 안내합니다.",points:["세종실록지리지와 삼국사기 등 옛 기록에서 우산도·우산국 관련 내용을 찾아볼 수 있습니다.","1900년 대한제국 칙령 제41호에는 울릉도와 함께 석도가 기록되어 있습니다.","독도, 다케시마, 리앙쿠르 록스 등 이름을 볼 때는 작성 시기와 자료의 성격을 함께 확인해야 합니다."],sourceLabel:"중등 이름·고문헌·고지도 단원, 고등 옛 기록·고지도 단원"},{id:"value",title:"독도에는 어떤 생명과 가치가 있나요?",summary:"철새의 쉼터, 풍부한 바다 생물, 화산섬과 천연기념물의 가치",content:"독도는 바람이 세고 흙이 적은 환경에서도 살아가는 식물과 다양한 바다 생물이 함께하는 섬입니다. 따뜻한 바다와 차가운 바다가 만나는 곳이라 플랑크톤이 풍부하고, 철새가 쉬어 가거나 번식하는 장소이기도 합니다. 자료에서는 독도를 자연환경과 해양자원을 함께 보전해야 하는 천연기념물 제336호 독도천연보호구역으로 소개합니다.",points:["괭이갈매기, 바다제비, 슴새 등 여러 철새가 독도를 쉬어 가거나 번식하는 곳으로 이용합니다.","독도 주변 바다는 어류·패류·해조류가 풍부하고, 해양 심층수와 가스 하이드레이트가 학습 자료에 소개됩니다.","1982년 천연기념물 제336호로 지정되었고, 1999년 독도천연보호구역으로 명칭이 바뀌었습니다."],sourceLabel:"초등 3~4학년 환경·천연기념물 단원, 중등 지형과 가치 단원"},{id:"people",title:"독도의 사람들은 어떻게 살아가고 지켜왔나요?",summary:"주민·독도경비대·등대 관리원과 생활 시설을 통해 보는 섬의 현재",content:"독도에는 주민과 독도경비대원, 등대 관리원, 공무원 등이 생활하고 있습니다. 선착장과 주민 숙소, 등대, 경비대 시설, 우체통과 물골 같은 장소를 살펴보면 독도가 자연만 있는 섬이 아니라 사람이 생활하고 관리하는 공간이라는 점을 알 수 있습니다. 독도에서 살아가기 위해 필요한 물과 이동, 안전의 문제도 함께 생각해 볼 수 있습니다.",points:["서도에는 물골이라는 자연 샘물이 있고, 자료에는 하루 약 1,000리터의 물이 나온다고 소개됩니다.","동도 선착장, 주민 숙소, 독도 등대, 독도경비대 등은 섬의 생활과 관리에 필요한 시설입니다.","독도를 지킨다는 말은 자연환경을 보전하고, 안전하게 생활하며, 자료를 바탕으로 가치를 알리는 일까지 포함합니다."],sourceLabel:"초등 3~4학년 독도에서 만나는 사람들 단원, 고등 광복 후 독도 단원"},{id:"future",title:"독도를 어떻게 알리고 평화롭게 표현할까요?",summary:"기록과 근거를 바탕으로 독도의 가치를 알리는 캠페인과 창작",content:"독도를 알리는 방법은 구호를 반복하는 데서 끝나지 않습니다. 옛 기록과 지도, 위치 자료, 자연환경, 섬에서 살아가는 사람들의 이야기를 근거로 삼아 다른 사람에게 이해하기 쉽게 전하는 활동이 필요합니다. 자료에서는 독도의 날 캠페인, 독도 체험관, 표기 오류를 찾아 수정 요청하기, 기념품과 홍보물 만들기 같은 활동을 제안합니다. 이번 모듈에서는 배운 내용을 굿즈와 상품 설명서로 바꾸며 근거 있는 메시지를 만들어 봅니다.",points:["자료를 인용할 때는 누가, 언제, 어떤 목적으로 만들었는지 확인합니다.","독도의 날 캠페인, 독도 체험관, 지도·표기 오류 알리기, 기념품 만들기 등 다양한 알림 활동이 있습니다.","다른 사람을 비난하기보다 배운 근거와 평화적 언어로 독도의 가치와 보전의 의미를 설명합니다."],sourceLabel:"초등 독도 알림이 활동, 중등 독도 학습 활동, 고등 독도·동해 바로 알리기 단원"}],t={id:"3",topic:"독도",title:"독도를 배우고, AI로 배움의 가치를 디자인하다",description:"독도의 위치·기록·자연·사람과 관리의 의미를 탐구하고, 생성형 AI를 활용해 근거 있는 굿즈와 상품 설명서를 만드는 모듈",steps:[{id:"step-1",title:"독도 주제 학습",description:"다섯 가지 테마를 눌러 독도에 관한 핵심 내용을 홈페이지에서 직접 학습해보세요.",content:"먼저 아래 테마를 차례로 살펴보며 독도의 위치, 이름과 기록, 자연환경, 사람과 관리, 알리기 활동을 이해해보세요. 읽은 내용 중 굿즈에 담고 싶은 사실이나 메시지를 한 가지 이상 메모해두면 다음 단계에서 활용할 수 있습니다.",learningThemes:e,externalLinks:[{url:"https://gemini.google.com/gem/1X21Of9Ls1y00m5wv9qavlZ9HpPGMKOlo?usp=sharing",label:"AI 챗봇으로 독도에 대해 더 질문하기",openInNewTab:!0}],showResourceDropdown:!0,dropdownResources:[{id:"resource-1",label:"초등 3~4학년 독도 학습 자료",url:"http://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Elementary34&levelId=eddok.d_0001"},{id:"resource-2",label:"초등 독도 학습 자료",url:"http://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Elementary&levelId=eddok.d_0002"},{id:"resource-3",label:"중학교 독도 학습 자료",url:"http://contents.nahf.or.kr/eddokViewer/contens.do?viewType=Middle&levelId=eddok.d_0003"},{id:"resource-4",label:"고등학교 독도 학습 자료",url:"http://contents.nahf.or.kr/eddokViewer/contens.do?viewType=High&levelId=eddok.d_0004"}],editableContent:!1},{id:"step-2",title:"독도 굿즈 디자인 생성",description:"학습 내용을 입력하고 빈 목업과 Gemini용 디자인 프롬프트를 준비해보세요.",content:"1단계에서 배운 독도의 모습과 가치를 티셔츠, 에코백, 핸드폰 케이스 등의 디자인으로 표현해보세요.",learningThemes:e,useGoodsDesignWorkspace:!0,editableContent:!1},{id:"step-3",title:"상품 설명서 제작",description:"굿즈의 의미와 사용 방법을 정리해 상품 설명서 이미지로 완성해보세요.",content:"디자인한 굿즈가 어떤 학습 내용에서 출발했는지, 누구에게 어떤 메시지를 전하는지 상품 설명서에 담아보세요.",useProductSheetWorkspace:!0,editableContent:!1},{id:"step-4",title:"최종 작품 제출",description:"완성된 독도 굿즈와 상품 설명서를 공유하고 서로의 아이디어를 살펴보세요.",content:"독도 굿즈 디자인과 상품 설명서가 완성되었습니다. Padlet에 결과물을 업로드하고, 다른 학습자들이 어떤 독도의 가치와 메시지를 선택했는지 비교해보세요.",showEmbeddedPadlet:!0,padletUrl:"https://padlet.com/ghdwns00610/padlet-tzs4uog4dr84u5gi",editableContent:!1}]};export{e as DOKDO_LEARNING_THEMES,t as MODULE_3_DATA};
